CREATE TABLE assay_b132_unique_deferrable (value integer,
-- ASSAY-FOCUS: unique-deferrable
  CONSTRAINT assay_b132_unique_deferrable UNIQUE (value) DEFERRABLE INITIALLY DEFERRED
);

cases.assertion:
BEGIN;
DO $$
BEGIN
  SET CONSTRAINTS ALL IMMEDIATE;
  BEGIN
    INSERT INTO assay_b132_unique_deferrable (value) VALUES (1), (1);
  EXCEPTION WHEN unique_violation THEN RETURN;
  END;
  RAISE EXCEPTION 'K01';
END $$;
ROLLBACK;

