CREATE TABLE assay_b132_fk_set_null_parent (a integer, b integer, PRIMARY KEY (a, b));
-- ASSAY-FOCUS: fk-set-null-columns
CREATE TABLE assay_b132_fk_set_null_child (a integer, b integer, CONSTRAINT assay_b132_fk_set_null FOREIGN KEY (a, b) REFERENCES assay_b132_fk_set_null_parent (a, b) ON DELETE SET NULL (b));

cases.assertion:
BEGIN;
DO $$
BEGIN
  INSERT INTO assay_b132_fk_set_null_parent (a, b) VALUES (1, 2);
  INSERT INTO assay_b132_fk_set_null_child (a, b) VALUES (1, 2);
  DELETE FROM assay_b132_fk_set_null_parent WHERE a = 1 AND b = 2;
  IF NOT EXISTS (
    SELECT 1 FROM assay_b132_fk_set_null_child WHERE a = 1 AND b IS NULL
  ) THEN
    RAISE EXCEPTION 'K01';
  END IF;
END $$;
ROLLBACK;

